 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}
/**
 * Membership and role changes, including the invariant that an organization always keeps one owner.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, memberResource, requireFound } from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Actor, Member, MemberWithUser, Role } from "@/types/member";

/** How many members are scanned when counting the remaining owners. */
const OWNER_SCAN_LIMIT = 100;

export async function listMembers(
  actor: Actor,
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:read", {
    kind: "organization",
    orgId: input.orgId,
  });
  return memberRepo.listMembers(input);
}

/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

